(function ($) {
  $(document).ready(function () {
    $(window).load(function () {
      $("#st-container").removeClass("disable-scrolling");
      $("#loading-animation").fadeOut();
      $("#preloader").delay(350).fadeOut(800);
      equalheight(".same-height");
    });

    if ($(window).width() > 1500) {
      $(".effect-wrapper").addClass("col-lg-3");
    }

    if ($(window).width() < 768) {
      $(".animated").removeClass("animated").removeClass("hiding");
      $(".stat span").removeClass("timer");
      $(".timeslot-label").addClass("stick-label");
    }

    if ($(window).height() < 512) {
      $("#bottom-navlinks")
        .removeClass("bottom-navlinks")
        .addClass("bottom-navlinks-small");
    }

    /*
     * Header state on page load.
     * The solid-header class forces the navigation bar to use the scrolled style immediately.
     */
    if ($(window).scrollTop() >= 100 || $("#top-header").hasClass("solid-header")) {
      $("#top-header").addClass("after-scroll");
      $("#logo-header .logo").removeClass("logo-light").addClass("logo-dark");
    }

    /*
     * Header state while scrolling.
     */
    $(window).scroll(function () {
      var scroll = $(this).scrollTop();
      var header = $("#top-header");
      var logo = $("#logo-header .logo");
      var rightNavButton = $(".right-nav-button");
      var stickyHeaderHeight = header.height() + $(".track-header").height();

      if (scroll >= 100 || header.hasClass("solid-header")) {
        header.addClass("after-scroll");
        logo.removeClass("logo-light").addClass("logo-dark");
      } else {
        header.removeClass("after-scroll");
        logo.removeClass("logo-dark").addClass("logo-light");
      }

      if (scroll >= $(".top-section").height() && $(window).width() > 767) {
        rightNavButton.removeClass("right-nav-button-hidden");
      } else if (scroll < $(".top-section").height() && $(window).width() > 767) {
        rightNavButton.addClass("right-nav-button-hidden");
      }

      $(".slot").each(function () {
        var offsetFromViewportTop = $(this).offset().top - scroll;
        var triggerHeight = stickyHeaderHeight + $(this).find(".slot-title").height();

        if (offsetFromViewportTop <= triggerHeight && offsetFromViewportTop >= 0) {
          $(".track-header.sticky")
            .find(".slot-detail")
            .html($(this).data("slotDetail"));
        }
      });
    });

    /*
     * Resize handling.
     */
    $(window).resize(function () {
      if ($(window).width() > 1500) {
        $(".effect-wrapper").addClass("col-lg-3");
      } else {
        $(".effect-wrapper").removeClass("col-lg-3");
      }

      if ($(window).width() < 768) {
        $(".same-height").css("height", "100%");
        $(".timeslot-label").addClass("stick-label");
      } else {
        $(".timeslot-label").removeClass("stick-label");

        if (sideMenuContainer.hasClass("st-menu-open")) {
          sideMenuContainer.removeClass("st-menu-open");
          $("body").css("overflow", "auto");
        }

        equalheight(".same-height");
      }

      if ($(window).height() < 512) {
        $(".st-menu").addClass("scrollable");
        $("#bottom-navlinks")
          .removeClass("bottom-navlinks")
          .addClass("bottom-navlinks-small");
      } else {
        $(".st-menu").removeClass("scrollable");
        $("#bottom-navlinks")
          .removeClass("bottom-navlinks-small")
          .addClass("bottom-navlinks");
      }
    });

    /*
     * Smooth scrolling for anchor links.
     */
    $("a[href*=#]:not([href=#])").click(function () {
      if (
        location.pathname.replace(/^\//, "") === this.pathname.replace(/^\//, "") &&
        location.hostname === this.hostname
      ) {
        var target = $(this.hash);
        target = target.length ? target : $("[name=" + this.hash.slice(1) + "]");

        if (target.length) {
          $("html,body").animate(
            {
              scrollTop: target.offset().top
            },
            1000
          );

          return false;
        }
      }
    });

    /*
     * Prevent empty anchor links from jumping the page.
     */
    $("a[href=#]").click(function (event) {
      event.preventDefault();
    });

    /*
     * Open schedule item from URL hash.
     */
    if (window.location.href.indexOf("schedule") > -1 && window.location.hash) {
      var hash = window.location.hash;
      $(hash).click();
    }

    /*
     * Stagger appear-animation elements.
     */
    var animationItems = $(".appear-animation");

    for (var i = 0, count = animationItems.length; i < count; i++) {
      var animationItem = animationItems[i];
      var offsetSum = animationItem.offsetLeft + animationItem.offsetTop;
      var delay = offsetSum / 1000;

      $(animationItem).css("transition-delay", "" + delay * 0.47 + "s");
      $(animationItem).css("transition-duration", "" + 0.2 + "s");
    }

    $(".appear-animation-trigger").appear(function () {
      setTimeout(function () {
        $(".appear-animation-trigger")
          .parent("div")
          .find(".appear-animation")
          .addClass("visible");
      }, 1000);
    });

    $(".animated").appear(
      function () {
        var item = $(this);
        var animation = item.data("animation");
        var delay = item.data("delay");

        if (delay) {
          setTimeout(function () {
            item.addClass(animation + " visible");
            item.removeClass("hiding");

            if (item.hasClass("counter")) {
              item.find(".timer").countTo();
            }
          }, delay);
        } else {
          item.addClass(animation + " visible");
          item.removeClass("hiding");

          if (item.hasClass("counter")) {
            item.find(".timer").countTo();
          }
        }
      },
      {
        accY: -150
      }
    );

    /*
     * Equal height helper.
     */
    equalheight = function (selector) {
      var currentTallest = 0;
      var currentRowStart = 0;
      var rowDivs = [];
      var element;
      var topPosition = 0;

      $(selector).each(function () {
        element = $(this);
        element.height("auto");
        topPosition = element.position().top;

        if (currentRowStart !== topPosition) {
          for (var currentDiv = 0; currentDiv < rowDivs.length; currentDiv++) {
            rowDivs[currentDiv].height(currentTallest);
          }

          rowDivs.length = 0;
          currentRowStart = topPosition;
          currentTallest = element.height();
          rowDivs.push(element);
        } else {
          rowDivs.push(element);
          currentTallest =
            currentTallest < element.height() ? element.height() : currentTallest;
        }

        for (var currentDiv2 = 0; currentDiv2 < rowDivs.length; currentDiv2++) {
          rowDivs[currentDiv2].height(currentTallest);
        }
      });
    };

    /*
     * Side menu.
     */
    var sideMenuContainer = $(".st-container");

    $("#menu-trigger").click(function (event) {
      event.stopPropagation();
      sideMenuContainer.toggleClass("st-menu-open");
    });

    $(".st-pusher").click(function () {
      if (sideMenuContainer.hasClass("st-menu-open")) {
        sideMenuContainer.removeClass("st-menu-open");
      }
    });

    /*
     * Schedule track headers.
     */
    $(".track-header").each(function () {
      var firstSlot = $(this).closest(".schedule-table").find(".slot").first();
      var slotDetail;

      while (slotDetail === undefined) {
        slotDetail = firstSlot.data("slotDetail");
        firstSlot = firstSlot.next();
      }

      $(this).find(".slot-detail").html(slotDetail);
    });

    /*
     * Use post feature image as top-section background.
     */
    $("#post-section .post-body p").each(function () {
      if ($(this).find(".feature-image").length) {
        var featureImageUrl = $(this).find(".feature-image").prop("src");

        $("#top-section")
          .css("background-image", "url(" + featureImageUrl + ")")
          .addClass("enable-overlay");
      }
    });

    /*
     * Speaker image sliders.
     */
    $(".slider").each(function () {
      $(this)
        .find(".slider-item")
        .first()
        .addClass("slider-current-item")
        .removeClass("hidden");

      if ($(this).find(".slider-item").length > 1) {
        $(this)
          .closest(".speaker-item")
          .find(".slider-next-item")
          .removeClass("hidden");
      }
    });

    $(".slider-next-item").click(function () {
      var container = $(this).closest("div");
      var nextItem = container.find(".slider-current-item").next();

      if (nextItem.length) {
        nextItem.addClass("slider-current-item").removeClass("hidden");

        container
          .find(".slider-current-item")
          .first()
          .removeClass("slider-current-item")
          .addClass("hidden");
      } else {
        container
          .find(".slider-item")
          .first()
          .addClass("slider-current-item")
          .removeClass("hidden");

        container
          .find(".slider-current-item")
          .last()
          .removeClass("slider-current-item")
          .addClass("hidden");
      }
    });

    /*
     * Reset videos in Bootstrap modals when closed.
     */
    $(".modal").on("hidden.bs.modal", function () {
      var iframe = $(this).find("iframe");
      iframe.attr("src", iframe.attr("src"));
    });

    /*
     * Store clicked slot in URL hash.
     */
    $(".slot").click(function () {
      location.hash = $(this).attr("id");
    });

    /*
     * Twitter feed.
     */
    if (typeof twitterFeedUrl !== "undefined") {
      $.getJSON(twitterFeedUrl, function (tweets) {
        $.each(tweets, function (index, tweet) {
          var tweetHtml =
            '<div class="tweet animated fadeInUp hidden">' +
            '<p class="tweet-text">' +
            linkifyTweetText(tweet.text) +
            "</p>" +
            '<p class="tweet-meta">by ' +
            '<a href="https://twitter.com/' +
            tweet.user.screen_name +
            '" target="_blank">@' +
            tweet.user.screen_name +
            "</a>" +
            "</p>" +
            "</div>";

          $("#tweets").append(tweetHtml);
        });

        rotateTweets();
      });

      function linkifyTweetText(text) {
        var urlPattern =
          /(\b(https?|ftp):\/\/[-A-Z0-9+&@#\/%?=~_|!:,.;]*[-A-Z0-9+&@#\/%=~_|])/gim;
        var linkedText = text.replace(
          urlPattern,
          '<a href="$1" target="_blank">$1</a>'
        );

        var wwwPattern = /(^|[^\/])(www\.[\S]+(\b|$))/gim;
        linkedText = linkedText.replace(
          wwwPattern,
          '$1<a href="http://$2" target="_blank">$2</a>'
        );

        var hashtagPattern = /#(\S*)/g;
        linkedText = linkedText.replace(
          hashtagPattern,
          '<a href="https://twitter.com/search?q=%23$1" target="_blank">#$1</a>'
        );

        var usernamePattern = /\B@([\w-]+)/gm;
        linkedText = linkedText.replace(
          usernamePattern,
          '<a href="https://twitter.com/$1" target="_blank">@$1</a>'
        );

        return linkedText;
      }

      function rotateTweets() {
        var tweets = $("#tweets").find(".tweet");
        var tweetIndex = 0;

        $(tweets.get(0)).removeClass("hidden");

        function showNextTweet() {
          var nextIndex = ++tweetIndex % tweets.length;

          $(tweets.get(nextIndex - 1)).addClass("hidden");
          $(tweets.get(nextIndex)).removeClass("hidden");
        }

        setInterval(showNextTweet, 5000);
      }
    }

    /*
     * Schedule theme filtering.
     */
    $("#themes").change(function () {
      if (!this.value) {
        $(".slot").removeClass("muted");
        $(".grid-item").removeClass("muted");
      } else {
        console.log("Filtering schedule to " + this.value);

        $(".slot:not(." + this.value + ")").addClass("muted");
        $(".grid-item:not(." + this.value + ")").addClass("muted");
        $("." + this.value).removeClass("muted");
      }

      var masonryGrid = Masonry.data($(".grid")[0]);

      if (masonryGrid) {
        masonryGrid.layout();
      }
    });
  });

  /*
   * Load Google platform script.
   */
  function loadGooglePlatformScript() {
    var script = document.createElement("script");

    script.type = "text/javascript";
    script.async = true;
    script.src = "https://apis.google.com/js/platform.js";

    var firstScript = document.getElementsByTagName("script")[0];
    firstScript.parentNode.insertBefore(script, firstScript);
  }

  /*
   * Static Google Map.
   */
  if (typeof staticGoogleMaps !== "undefined") {
    $("#canvas-map")
      .addClass("image-section")
      .css(
        "background-image",
        "url(https://maps.googleapis.com/maps/api/staticmap?zoom=17" +
          "&center=" +
          mobileCenterMapCoordinates +
          "&size=" +
          $(window).width() +
          "x700" +
          "&scale=2" +
          "&language=en" +
          "&markers=icon:" +
          icon +
          "|" +
          eventPlaceCoordinates +
          "&maptype=roadmap" +
          "&style=visibility:on|lightness:40|gamma:1.1|weight:0.9" +
          "&style=element:labels|visibility:off" +
          "&style=feature:water|hue:0x0066ff" +
          "&style=feature:road|visibility:on" +
          "&style=feature:road|element:labels|saturation:-30)"
      );
  }

  /*
   * Interactive Google Map.
   */
  if (typeof googleMaps !== "undefined") {
    var map;
    var autocomplete;
    var directionsRenderer;
    var geocoder;
    var routeLine;
    var userLocation;
    var markers = [];

    var directionsService = new google.maps.DirectionsService();
    var customStyleName = "custom_style";

    function initMap() {
      directionsRenderer = new google.maps.DirectionsRenderer({
        suppressMarkers: true
      });

      geocoder = new google.maps.Geocoder();

      routeLine = new google.maps.Polyline({
        strokeColor: "#03a9f4",
        strokeOpacity: 1,
        strokeWeight: 2
      });

      var defaultMapStyle = [
        {
          stylers: [
            {
              lightness: 40
            },
            {
              visibility: "on"
            },
            {
              gamma: 0.9
            },
            {
              weight: 0.4
            }
          ]
        },
        {
          elementType: "labels",
          stylers: [
            {
              visibility: "on"
            }
          ]
        },
        {
          featureType: "water",
          stylers: [
            {
              color: "#5dc7ff"
            }
          ]
        },
        {
          featureType: "road",
          stylers: [
            {
              visibility: "off"
            }
          ]
        }
      ];

      var zoomedMapStyle = [
        {
          stylers: [
            {
              lightness: 40
            },
            {
              visibility: "on"
            },
            {
              gamma: 1.1
            },
            {
              weight: 0.9
            }
          ]
        },
        {
          elementType: "labels",
          stylers: [
            {
              visibility: "off"
            }
          ]
        },
        {
          featureType: "water",
          stylers: [
            {
              color: "#5dc7ff"
            }
          ]
        },
        {
          featureType: "road",
          stylers: [
            {
              visibility: "on"
            }
          ]
        },
        {
          featureType: "road",
          elementType: "labels",
          stylers: [
            {
              saturation: -30
            }
          ]
        }
      ];

      var mapOptions = {
        zoom: 17,
        minZoom: 2,
        scrollwheel: false,
        panControl: false,
        draggable: true,
        zoomControl: false,
        zoomControlOptions: {
          position: google.maps.ControlPosition.RIGHT_TOP
        },
        scaleControl: false,
        mapTypeControl: false,
        streetViewControl: false,
        center: centerMap,
        mapTypeControlOptions: {
          mapTypeIds: [google.maps.MapTypeId.ROADMAP, customStyleName]
        },
        mapTypeId: customStyleName
      };

      if ($(window).width() < 768) {
        mapOptions.center = mobileCenterMap;
      }

      if (googleMaps === "logistics") {
        mapOptions.zoom = 5;
        mapOptions.zoomControl = true;
      }

      map = new google.maps.Map(document.getElementById("canvas-map"), mapOptions);

      var eventMarker = new google.maps.Marker({
        position: eventPlace,
        animation: google.maps.Animation.DROP,
        icon: icon,
        map: map
      });

      markers.push(eventMarker);

      var defaultStyledMap = new google.maps.StyledMapType(defaultMapStyle, {
        name: "Default Style"
      });

      var zoomedStyledMap = new google.maps.StyledMapType(zoomedMapStyle, {
        name: "Zoomed Style"
      });

      map.mapTypes.set("default", defaultStyledMap);
      map.mapTypes.set("zoomed", zoomedStyledMap);

      if (googleMaps === "logistics") {
        map.setMapTypeId("default");

        var locationInput = document.getElementById("location-input");
        autocomplete = new google.maps.places.Autocomplete(locationInput);

        google.maps.event.addListener(autocomplete, "place_changed", function () {
          eventMarker.setVisible(false);

          var place = autocomplete.getPlace();

          if (place.geometry === "undefined" || !place.geometry) {
            return;
          }

          var address = "";

          if (place.address_components) {
            address = [
              (place.address_components[0] &&
                place.address_components[0].short_name) ||
                "",
              (place.address_components[1] &&
                place.address_components[1].short_name) ||
                "",
              (place.address_components[2] &&
                place.address_components[2].short_name) ||
                ""
            ].join(" ");
          }

          geocoder.geocode(
            {
              address: address
            },
            function (results, status) {
              if (status === google.maps.GeocoderStatus.OK) {
                userLocation = results[0].geometry.location;
                buildRoute(userLocation, "TRANSIT");
              } else {
                alert("Geocode was not successful for the following reason: " + status);
              }
            }
          );
        });
      } else {
        map.setMapTypeId("zoomed");
      }

      function buildRoute(origin, travelMode) {
        var request = {
          origin: origin,
          destination: eventPlace,
          travelMode: google.maps.TravelMode[travelMode]
        };

        directionsService.route(request, function (response, status) {
          if (status === google.maps.DirectionsStatus.OK) {
            map.setMapTypeId("zoomed");

            directionsRenderer.setMap(map);
            directionsRenderer.setDirections(response);

            var leg = response.routes[0].legs[0];

            addIconMarker(leg.start_location);
            addIconMarker(leg.end_location);

            $("#distance").text(leg.distance.text);
            $("#estimateTime").text(leg.duration.text);
            $("#mode-select").val(travelMode);
            $("#mode").removeClass("hidden");

            var modeIconHref = $("#mode-icon use").attr("xlink:href");
            modeIconHref =
              modeIconHref.substring(0, modeIconHref.indexOf("#") + 1) +
              "icon-" +
              travelMode.toLowerCase();

            $("#mode-icon use").attr("xlink:href", modeIconHref);
          } else if (
            status !== google.maps.DirectionsStatus.OK &&
            travelMode !== "DRIVING"
          ) {
            buildRoute(origin, "DRIVING");
          } else {
            var routePath = routeLine.getPath();

            routePath.push(origin);
            routePath.push(eventPlace);

            addIconMarker(origin);
            addIconMarker(eventPlace);

            var bounds = new google.maps.LatLngBounds();

            bounds.extend(origin);
            bounds.extend(eventPlace);

            map.fitBounds(bounds);
            routeLine.setMap(map);

            var distanceKm = Math.round(
              google.maps.geometry.spherical.computeDistanceBetween(
                origin,
                eventPlace
              ) / 1000
            );

            $("#distance").text(distanceKm + " km");
            $("#estimateTime").text("");
            $("#find-flight").removeClass("hidden");
            $("#mode").addClass("hidden");
          }
        });

        clearMarkers();

        $("#find-way").addClass("location-active");
        updateResultName(origin);
        $("#find-way h3").removeClass("fadeInUp").addClass("fadeOutDown");
      }

      function locateUser() {
        if (navigator.geolocation) {
          navigator.geolocation.getCurrentPosition(function (position) {
            userLocation = new google.maps.LatLng(
              position.coords.latitude,
              position.coords.longitude
            );

            buildRoute(userLocation, "TRANSIT");
          });
        }
      }

      function addIconMarker(position) {
        var marker = new google.maps.Marker({
          position: position,
          map: map,
          icon: icon
        });

        markers.push(marker);
      }

      function addDefaultMarker(position) {
        var marker = new google.maps.Marker({
          position: position,
          map: map
        });

        markers.push(marker);
      }

      function clearMarkers() {
        for (var markerIndex = 0; markerIndex < markers.length; markerIndex++) {
          markers[markerIndex].setMap(null);
        }

        markers = [];
      }

      function animateZoom(targetZoom) {
        var currentZoom = map.getZoom();
        var stepDelay = 50;
        var zoomDifference = Math.abs(targetZoom - currentZoom);
        var zoomDirection = targetZoom > currentZoom ? 1 : -1;

        for (var step = 0; step < zoomDifference; step++) {
          setTimeout(function () {
            currentZoom += zoomDirection;
            map.setZoom(currentZoom);
          }, (step + 1) * stepDelay);
        }
      }

      function updateResultName(location) {
        geocoder.geocode(
          {
            latLng: location
          },
          function (results, status) {
            if (status === google.maps.GeocoderStatus.OK && results[1]) {
              var addressComponents = results[1].address_components;

              $.each(addressComponents, function (index, component) {
                if (component.types[0] === "locality") {
                  $("#result-name").text(component.long_name);
                  return false;
                }
              });
            }
          }
        );
      }

      $("#mode-select").change(function () {
        var selectedMode = $(this).val();
        buildRoute(userLocation, selectedMode);
      });

      $("#direction-locate").click(locateUser);

      $("#direction-cancel").click(function () {
        $("#find-way").removeClass("location-active");
        $("#location-input").val("");
        $("#find-flight").addClass("hidden");

        clearMarkers();

        directionsRenderer.setMap(null);
        routeLine.setMap(null);

        map.setMapTypeId("default");
        map.panTo(eventPlace);

        if ($(window).width() < 768) {
          map.setCenter(mobileCenterMap);
        } else {
          map.setCenter(centerMap);
        }

        addIconMarker(eventPlace);
        animateZoom(5);

        $("#find-way h3").removeClass("fadeOutDown").addClass("fadeInUp");
      });

      if (
        typeof autoDirectionEnabled !== "undefined" &&
        autoDirectionEnabled === true
      ) {
        locateUser();
      }
    }

    google.maps.event.addDomListener(window, "load", initMap);
  }
})(jQuery);